SELECT mp.subject_id AS male_patient_id, fp.subject_id AS female_patient_id, mcq.medication_count, fcq.medication_count, mcp.avg_percentile_rank, fcp.avg_percentile_rank, mlom.length_of_stay, flom.length_of_stay, mlomtq.subject_id AS male_patient_id_top_quartile, flomtq.subject_id AS female_patient_id_top_quartile FROM male_complexity_quartiles mcq JOIN female_complexity_quartiles fcq ON mcq.subject_id = fcq.subject_id JOIN male_complexity_avg_percentile mcp ON mcq.subject_id = mcp.subject_id JOIN female_complexity_avg_percentile fcp ON fcq.subject_id = fcp.subject_id JOIN male_los_mortality mlom ON mlom.subject_id = mcq.subject_id JOIN female_los_mortality flom ON flom.subject_id = fcq.subject_id JOIN male_los_mortality_top_quartile mlomtq ON mlomtq.subject_id = mcq.subject_id JOIN female_los_mortality_top_quartile flomtq ON flomtq.subject_id = fcq.subject_id JOIN patients p ON p.subject_id = mcq.subject_id JOIN admissions a ON a.subject_id = p.subject_id WHERE a.admission_type_id IN (SELECT admission_type_id FROM admissions WHERE name = 'Multi-trauma') ORDER BY mcq.medication_count NULLS LAST;